const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const {JSDOM}=require('jsdom');
test('cache checkbox opens once, calibrates without writing and leaves excluded rows disabled',async()=>{
 const dom=new JSDOM('<div id="modelDocumentList"></div><span id="viewerInteractionRoute"></span>',{runScripts:'outside-only'}),w=dom.window,c=dom.getInternalVMContext();
 try{
  for(const file of ['model_document_collection.js','viewer_interaction.js','live_document_adoption.js','cache_snapshot_viewer.js','cad_sim.js'])vm.runInContext(fs.readFileSync(path.join(__dirname,file),'utf8'),c);
  vm.runInContext(`document.removeEventListener('DOMContentLoaded',init);_cmdShow=()=>{};_simulationDebug=()=>{};
   window.opens=0;window.writes=0;window.openInputs=[];
   window._simulationEnvironmentWorkspace={store:{state:{workspace:{workspace_gid:'10',row_version:1}}}};
   window.model={document_gid:'2',role:'primary',media_type:'model/vnd.jt',source_kind:'teamcenter_cache_snapshot',cache_binding:{batch_id:'batch'},product_tree:{state:'ready',source:'teamcenter_cache_snapshot',node_count:2,pages:{roots:{}},nodes:[{node_key:'cache:root',cache_node_key:'root',name:'Root',item_revision_uid:'r',parent_key:null,has_children:true,visible:true,occurrence_path:[]},{node_key:'cache:missing',cache_node_key:'missing',name:'Missing',item_revision_uid:'r',parent_key:'cache:root',has_children:false,visible:true,occurrence_path:[]}]}};
   _modelDocumentCollection={state:{documents:[model]}};
   window.local={state:'ready',scope:{workspace_gid:'10',document_gid:'2'},visibilityContext:'context',executeIntent(){throw Error('online_forbidden');},readVisibility:async({source_nodes})=>({visibility_context:'context',nodes:source_nodes.map(n=>({source_node_id:n.source_node_id,visible:false,visibility_state:'hidden'}))}),executeCachedIntent:async()=>{writes++;return{ok:true,visible:true};}};
   window._localViewerInteraction=()=>local;
   window.AI00CacheSnapshotViewer={...window.AI00CacheSnapshotViewer,create:options=>({open:async input=>{opens++;openInputs.push(input);if(window.failOpen)throw Error('interaction_bridge_timeout');if(window.failUnknown)throw Object.assign(Error('cancelled'),{cache_effect_unknown:true});options.onProgress({...input,stage:'node_excluded',name:'Missing <node>',error_code:'relative_missing_absolute_may_be_placeholder'});return{root_node_key:input.root_node_key??null,visibility_context:'context',workspace_row_version:2,document_gid:'2',document_session:'sha256:'+'a'.repeat(64),package_hash:'package',identity:input.cache_binding,node_map:{root:{instance_id:'generated-root',parent_node_key:null},missing:{instance_id:'generated-missing',parent_node_key:'root'}},excluded:[{node_key:'missing',name:'Missing <node>',error_code:'relative_missing_absolute_may_be_placeholder'}]};}})};
   window._ensureLocalViewerReady=(document,node)=>window._ensureCacheSnapshotViewer(document,node);
   const adapter=AI00LiveDocumentAdoption.createAdapter({getStore:()=>window._simulationEnvironmentWorkspace.store,getLocalInteraction:()=>local,ensureCachedReady:window._ensureLocalViewerReady});
   window._actOnModelNode=adapter.actOnProductNode;
   _renderModelDocuments([model]);document.querySelector('.cs-model-document-toggle').click();`,c);
  const check=w.document.querySelector('.cs-alternate-tree-check');assert.equal(check.disabled,false);assert.equal(check.dataset.visibility,'unknown','persisted visible cannot claim runtime state');
  check.click();await new Promise(r=>setImmediate(r));
  assert.equal(w.opens,1);assert.equal(w.openInputs[0].root_node_key,'root');assert.equal(w.writes,0);assert.equal(check.dataset.visibility,'unknown');assert.equal(check.disabled,false);assert.match(check.title,/部分节点未加载/);
  assert.equal(w.model._cacheViewer.native_visibility.root.visible,false);
  const child=vm.runInContext(`_buildProductTreeItem(AI00ModelDocumentCollection.buildProductForest(model.product_tree.nodes)[0].children[0],'2')`,c);
  const missing=child.querySelector('input');assert.equal(missing.disabled,true);assert.equal(missing.dataset.visibility,'unknown');assert.match(missing.title,/缓存缺少相对装配位置/);
  const reasons=w.document.querySelector('.cs-cache-exclusions');assert.equal(reasons.tagName,'DETAILS');assert.equal(reasons.querySelector('summary').textContent,'1 个节点未加载');
  assert.match(reasons.textContent,/Missing <node>：缓存缺少相对装配位置，现有绝对矩阵不能单独作为可靠位置/);assert.equal(reasons.querySelector('node'),null);
  assert.doesNotMatch(reasons.textContent,/relative_missing_absolute_may_be_placeholder/);
  assert.match(w.document.getElementById('viewerInteractionRoute').textContent,/部分缓存节点未加载/);
  assert.match(vm.runInContext(`_cacheSnapshotReason('transform_composition_mismatch')`,c),/父级位置组合后/);
  check.click();await new Promise(r=>setImmediate(r));assert.equal(w.opens,1);assert.equal(w.writes,1);assert.equal(check.dataset.visibility,'unknown');
  assert.equal(JSON.stringify(w.model).includes('_cacheViewer'),false);
  assert.ok(w._cacheSnapshotResumeCandidate('10','2'));
  vm.runInContext(`model.product_tree.nodes.push({node_key:'cache:other',cache_node_key:'other',name:'Other',item_revision_uid:'r',parent_key:null,has_children:false,visible:null,visibility_state:'unknown'});`,c);
  const outside=vm.runInContext(`_buildProductTreeItem(AI00ModelDocumentCollection.buildProductForest(model.product_tree.nodes)[1],'2')`,c).querySelector('input');
  assert.equal(outside.disabled,false,'unloaded sibling must remain loadable');assert.equal(outside.dataset.visibility,'unknown');
  await w._ensureCacheSnapshotViewer(w.model,w.model.product_tree.nodes.at(-1));
  assert.equal(w.opens,2);assert.equal(w.openInputs[1].root_node_key,'other','another branch must not reuse the previous scope');
  await vm.runInContext(`_openCachedModelDocument(model)`,c);assert.equal(w.writes,1,'document open action must not show anything');
  w._invalidateCacheSnapshotVisibility();assert.equal(check.dataset.visibility,'unknown');assert.equal(w.model._cacheViewer,undefined);assert.equal(w.document.querySelector('.cs-cache-exclusions'),null);
  assert.ok(w._cacheSnapshotResumeCandidate('10','2'),'switch away retains only structural candidate');
  w.failUnknown=true;await assert.rejects(w._ensureCacheSnapshotViewer(w.model,w.model.product_tree.nodes.at(-1)),/cancelled/);
  assert.equal(w._cacheSnapshotResumeCandidate('10','2'),null,'unknown native effect quarantines even with a cancelled step code');w.failUnknown=false;
  await w._ensureCacheSnapshotViewer(w.model,w.model.product_tree.nodes[0]);w._invalidateCacheSnapshotVisibility();
  w.failOpen=true;await assert.rejects(w._ensureCacheSnapshotViewer(w.model,w.model.product_tree.nodes.at(-1)),/interaction_bridge_timeout/);
  assert.equal(w._cacheSnapshotResumeCandidate('10','2'),null,'ambiguous bridge timeout quarantines the prior candidate');w.failOpen=false;
  w._invalidateCacheSnapshotVisibility('outcome_unknown');assert.equal(w._cacheSnapshotResumeCandidate('10','2'),null,'unknown effect quarantines the candidate');
  await w._ensureCacheSnapshotViewer(w.model,w.model.product_tree.nodes[0]);
  assert.ok(w._cacheSnapshotResumeCandidate('10','2'));
  w.dispatchEvent(new w.Event('pagehide'));assert.equal(w._cacheSnapshotResumeCandidate('10','2'),null,'new page has no candidate');
 }finally{w.close();}
});
test('cached document expands and reads details exclusively through fixed batch query@2',async()=>{
 const dom=new JSDOM('<div id="modelDocumentList"></div><div id="csDetailPanel"></div><div id="dpVisLeft"></div><div id="dpVisRight"></div>',{runScripts:'outside-only'});
 const c=dom.getInternalVMContext();
 for(const file of ['model_document_collection.js','teamcenter_online_source.js','tree_projection_cache.js','cache_snapshot_source.js','cad_sim.js'])vm.runInContext(fs.readFileSync(path.join(__dirname,file),'utf8'),c);
 vm.runInContext(`document.removeEventListener('DOMContentLoaded',init);
  _modelDocumentCollection=AI00ModelDocumentCollection.createCollection();
  window._simulationEnvironmentWorkspace={store:{state:{workspace:{workspace_gid:'10',row_version:1}}}};
  window.calls=[];window.binding={batch_id:'a'.repeat(32),generation:'b'.repeat(32),snapshot_hash:null,schema_version:1};
  window.doc={document_gid:'2',role:'primary',source_kind:'teamcenter_cache_snapshot',source_identity_hash:'id',cache_binding:binding,media_type:'application/vnd.siemens.teamcenter.visualization-document'};
  _requestVisMockupCommand=async()=>{throw Error('live_tc_must_not_run');};
  _invokeCapability=async(id,p,options)=>{calls.push({id,p,options});if(id.endsWith('model_document.search'))return {items:[doc]};
   const root={node_key:'root',occurrence_id:'root',parent_occurrence_id:null,occurrence_path:[],name:'old root',has_children:true};
   return {identity:binding,manifest:{status:'completed',node_count:2},next_cursor:null,nodes:p.scope==='children'?[{...root,node_key:'child',occurrence_id:'child',parent_occurrence_id:'root',has_children:false}]:[{...root,...(p.scope==='node'?{properties_result:{properties:{name:'old detail'}}}:{})}]};};
  _persistModelProjectionCache=async()=>{};
 `,c);
 try{
  await vm.runInContext(`_refreshModelDocuments()`,c);
  const row=dom.window.document.querySelector('.cs-model-document-summary');assert.match(row.textContent,/缓存/);
  const tree=dom.window.document.querySelector('.cs-model-document-tree');
  if(tree.classList.contains('hidden'))row.querySelector('button').click();
  dom.window.document.querySelector('.cs-alternate-tree-toggle').click();
  await new Promise(r=>setImmediate(r));
  assert.equal(dom.window.document.querySelectorAll('.cs-alternate-tree-item').length,2);
  assert.ok([...dom.window.document.querySelectorAll('input')].every(x=>x.disabled&&x.dataset.visibility==='unknown'));
  dom.window.document.querySelector('.cs-alternate-tree-name').click();await new Promise(r=>setImmediate(r));
  assert.match(dom.window.document.getElementById('dpVisLeft').textContent,/缓存批次/);
  assert.match(dom.window.document.getElementById('dpVisRight').textContent,/old detail/);
  assert.ok(dom.window.calls.filter(x=>x.id==='simulation.model_cache.query').every(x=>x.options.version===2&&x.p.batch_id===dom.window.binding.batch_id));
 }finally{dom.window.close();}
});
